/**
 * Event Bus
 * In-memory publish/subscribe message broker
 */

type EventCallback = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /**
   * Publish an event to all subscribers
   */
  publish(event: string, payload: any): void {
    const callbacks = this.subscribers.get(event);
    if (callbacks) {
      callbacks.forEach((callback) => {
        try {
          callback(payload);
        } catch (error) {
          console.error(`Error in subscriber for event "${event}":`, error);
        }
      });
    }
  }

  /**
   * Subscribe to an event
   */
  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);
  }
}

export const eventBus = new EventBus();

/**
 * User Service
 * Manages user CRUD operations
 */

import { randomUUID } from "crypto";

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface CreateUserInput {
  name: string;
  email: string;
}

export interface UpdateUserInput {
  name?: string;
  email?: string;
}

export class UserService {
  private userStore: Map<string, User> = new Map();

  /**
   * Create a new user
   */
  create(input: CreateUserInput): User {
    const user: User = {
      id: randomUUID(),
      name: input.name,
      email: input.email,
    };
    this.userStore.set(user.id, user);
    return user;
  }

  /**
   * Get user by ID
   */
  getById(id: string): User | null {
    return this.userStore.get(id) || null;
  }

  /**
   * Get all users
   */
  getAll(): User[] {
    return Array.from(this.userStore.values());
  }

  /**
   * Update user
   */
  update(id: string, input: UpdateUserInput): User | null {
    const user = this.userStore.get(id);
    if (!user) return null;

    if (input.name !== undefined) user.name = input.name;
    if (input.email !== undefined) user.email = input.email;

    this.userStore.set(id, user);
    return user;
  }

  /**
   * Delete user
   */
  delete(id: string): boolean {
    return this.userStore.delete(id);
  }
}

export const userService = new UserService();

/**
 * Project Service
 * Manages projects and membership
 */

import { randomUUID } from "crypto";

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export interface CreateProjectInput {
  name: string;
  description: string;
}

export interface UpdateProjectInput {
  name?: string;
  description?: string;
}

export interface AddMemberInput {
  userId: string;
}

export interface RemoveMemberInput {
  userId: string;
}

export class ProjectService {
  private projectStore: Map<string, Project> = new Map();

  /**
   * Create a new project
   */
  create(input: CreateProjectInput): Project {
    const project: Project = {
      id: randomUUID(),
      name: input.name,
      description: input.description,
      memberIds: [],
    };
    this.projectStore.set(project.id, project);
    return project;
  }

  /**
   * Get project by ID
   */
  getById(id: string): Project | null {
    return this.projectStore.get(id) || null;
  }

  /**
   * Get all projects
   */
  getAll(): Project[] {
    return Array.from(this.projectStore.values());
  }

  /**
   * Update project
   */
  update(id: string, input: UpdateProjectInput): Project | null {
    const project = this.projectStore.get(id);
    if (!project) return null;

    if (input.name !== undefined) project.name = input.name;
    if (input.description !== undefined)
      project.description = input.description;

    this.projectStore.set(id, project);
    return project;
  }

  /**
   * Delete project
   */
  delete(id: string): boolean {
    return this.projectStore.delete(id);
  }

  /**
   * Add member to project
   */
  addMember(projectId: string, userId: string): Project | null {
    const project = this.projectStore.get(projectId);
    if (!project) return null;

    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
      this.projectStore.set(projectId, project);
    }

    return project;
  }

  /**
   * Remove member from project
   */
  removeMember(projectId: string, userId: string): Project | null {
    const project = this.projectStore.get(projectId);
    if (!project) return null;

    project.memberIds = project.memberIds.filter((id) => id !== userId);
    this.projectStore.set(projectId, project);

    return project;
  }
}

export const projectService = new ProjectService();

/**
 * Task Service
 * Manages tasks with status transitions
 */

import { randomUUID } from "crypto";
import { eventBus } from "../event-bus.js";

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface CreateTaskInput {
  title: string;
  description: string;
  projectId: string;
}

export interface UpdateTaskInput {
  title?: string;
  description?: string;
}

export interface ChangeStatusInput {
  newStatus: TaskStatus;
}

export interface AssignInput {
  assigneeId: string;
}

export class TaskService {
  private taskStore: Map<string, Task> = new Map();

  /**
   * Create a new task
   */
  create(input: CreateTaskInput): Task {
    const task: Task = {
      id: randomUUID(),
      title: input.title,
      description: input.description,
      status: "todo",
      assigneeId: null,
      projectId: input.projectId,
    };
    this.taskStore.set(task.id, task);
    return task;
  }

  /**
   * Get task by ID
   */
  getById(id: string): Task | null {
    return this.taskStore.get(id) || null;
  }

  /**
   * Get tasks by project
   */
  getByProject(projectId: string): Task[] {
    return Array.from(this.taskStore.values()).filter(
      (task) => task.projectId === projectId
    );
  }

  /**
   * Update task
   */
  update(id: string, input: UpdateTaskInput): Task | null {
    const task = this.taskStore.get(id);
    if (!task) return null;

    if (input.title !== undefined) task.title = input.title;
    if (input.description !== undefined) task.description = input.description;

    this.taskStore.set(id, task);
    return task;
  }

  /**
   * Delete task
   */
  delete(id: string): boolean {
    return this.taskStore.delete(id);
  }

  /**
   * Assign task to a user
   */
  assign(taskId: string, assigneeId: string): Task | null {
    const task = this.taskStore.get(taskId);
    if (!task) return null;

    const oldAssigneeId = task.assigneeId;
    task.assigneeId = assigneeId;
    this.taskStore.set(taskId, task);

    // Publish event
    eventBus.publish("task.assigned", {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
    });

    return task;
  }

  /**
   * Change task status with validation
   * Forward-only transitions: todo -> in-progress -> done
   */
  changeStatus(taskId: string, input: ChangeStatusInput): Task | null {
    const task = this.taskStore.get(taskId);
    if (!task) return null;

    const statusOrder = ["todo", "in-progress", "done"];
    const currentIndex = statusOrder.indexOf(task.status);
    const newIndex = statusOrder.indexOf(input.newStatus);

    // Only allow forward transitions
    if (newIndex <= currentIndex) {
      throw new Error(
        `Cannot transition from ${task.status} to ${input.newStatus}`
      );
    }

    const oldStatus = task.status;
    task.status = input.newStatus;
    this.taskStore.set(taskId, task);

    // Publish event
    eventBus.publish("task.statusChanged", {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus: task.status,
    });

    return task;
  }
}

export const taskService = new TaskService();

/**
 * Comment Service
 * Manages comments on tasks
 */

import { randomUUID } from "crypto";
import { eventBus } from "../event-bus.js";
import { taskService } from "./task-service.js";

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string;
}

export interface CreateCommentInput {
  taskId: string;
  authorId: string;
  body: string;
}

export class CommentService {
  private commentStore: Map<string, Comment> = new Map();

  /**
   * Create a new comment
   */
  create(input: CreateCommentInput): Comment | null {
    // Verify task exists
    const task = taskService.getById(input.taskId);
    if (!task) return null;

    const comment: Comment = {
      id: randomUUID(),
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body,
      createdAt: new Date().toISOString(),
    };

    this.commentStore.set(comment.id, comment);

    // Publish event
    eventBus.publish("comment.added", {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle: task.title,
      authorId: comment.authorId,
      authorName: comment.authorId, // Will be resolved by caller
    });

    return comment;
  }

  /**
   * Get comment by ID
   */
  getById(id: string): Comment | null {
    return this.commentStore.get(id) || null;
  }

  /**
   * Get comments by task
   */
  getByTask(taskId: string): Comment[] {
    return Array.from(this.commentStore.values()).filter(
      (comment) => comment.taskId === taskId
    );
  }

  /**
   * Delete comment
   */
  delete(id: string): boolean {
    return this.commentStore.delete(id);
  }
}

export const commentService = new CommentService();

/**
 * Notification Service
 * Creates notifications from events
 */

import { randomUUID } from "crypto";
import { eventBus } from "../event-bus.js";

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string;
}

export class NotificationService {
  private notificationStore: Map<string, Notification> = new Map();

  constructor() {
    this.subscribeToEvents();
  }

  /**
   * Subscribe to events from other services
   */
  private subscribeToEvents(): void {
    // Listen to task.assigned event
    eventBus.subscribe(
      "task.assigned",
      (payload: {
        taskId: string;
        taskTitle: string;
        assigneeId: string;
      }) => {
        if (payload.assigneeId) {
          this.createNotification(
            payload.assigneeId,
            `You have been assigned to task: ${payload.taskTitle}`
          );
        }
      }
    );

    // Listen to task.statusChanged event
    eventBus.subscribe(
      "task.statusChanged",
      (payload: {
        taskId: string;
        taskTitle: string;
        assigneeId: string | null;
        oldStatus: string;
        newStatus: string;
      }) => {
        if (payload.assigneeId) {
          this.createNotification(
            payload.assigneeId,
            `Task "${payload.taskTitle}" status changed to ${payload.newStatus}`
          );
        }
      }
    );

    // Listen to comment.added event
    eventBus.subscribe(
      "comment.added",
      (payload: {
        commentId: string;
        taskId: string;
        taskTitle: string;
        authorId: string;
        authorName: string;
      }) => {
        // This would normally notify the task assignee,
        // but we'd need task context. For now, we just log.
        // In a real system, this would look up the task and notify the assignee.
      }
    );
  }

  /**
   * Create a notification (internal method)
   */
  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.notificationStore.set(notification.id, notification);
    return notification;
  }

  /**
   * Get notifications for a user
   */
  getByUser(userId: string): Notification[] {
    return Array.from(this.notificationStore.values()).filter(
      (notif) => notif.userId === userId
    );
  }

  /**
   * Mark notification as read
   */
  markAsRead(notificationId: string): Notification | null {
    const notification = this.notificationStore.get(notificationId);
    if (!notification) return null;

    notification.read = true;
    this.notificationStore.set(notificationId, notification);
    return notification;
  }
}

